import 'package:flutter/material.dart';
import 'package:flutter/widgets.dart';
import 'app_theme.dart';

extension ContextSnackBar on BuildContext {
  void showSuccess(String message, {Duration duration = const Duration(seconds: 3), String? actionLabel, VoidCallback? onAction}) {
    final action = (actionLabel != null && onAction != null)
        ? SnackBarAction(label: actionLabel, onPressed: onAction, textColor: Colors.white)
        : null;
    ScaffoldMessenger.of(this).showSnackBar(AppTheme.successSnackBar(this, message, duration: duration, action: action));
  }

  void showError(String message, {Duration duration = const Duration(seconds: 4), String? actionLabel, VoidCallback? onAction}) {
    final action = (actionLabel != null && onAction != null)
        ? SnackBarAction(label: actionLabel, onPressed: onAction, textColor: Colors.white)
        : null;
    ScaffoldMessenger.of(this).showSnackBar(AppTheme.errorSnackBar(this, message, duration: duration, action: action));
  }
}

import 'package:flutter/material.dart';

// Central spacing and sizing constants for consistent layout
class AppSpacing {
  // standard horizontal page padding
  static const double page = 16.0;

  // internal card padding
  static const double card = 12.0;

  // vertical gap between elements
  static const double gap = 12.0;

  // approximate FAB+margin height used to keep content above a floating button
  static const double fabHeight = 56.0;
  static const double fabMargin = 16.0;

  // total footer spacer height to avoid FAB overlap
  static double footerHeight(BuildContext context) {
    return MediaQuery.of(context).padding.bottom + fabHeight + fabMargin;
  }
}

// Central radii used across components to keep the UI cohesive
class AppRadius {
  static const double small = 8.0;
  static const double medium = 12.0;
  static const double large = 16.0;
}

// Shared elevation values
class AppElevation {
  static const double card = 2.0;
  static const double appBar = 1.0;
  static const double bottomNav = 6.0;
}

