import '../../../../core/providers/core_providers.dart';
import '../../../../core/services/net_worth_service.dart';
import '../../../../core/utils/date_utils.dart';
import '../../../accounts/presentation/providers/account_providers.dart';
import '../../../transactions/domain/entities/ledger_transaction.dart';
import '../../../transactions/presentation/providers/transaction_providers.dart';
import '../../../../shared/domain/enums/transaction_type.dart';

final netWorthServiceProvider =
    Provider((ref) => NetWorthService(ref.watch(balanceCalculatorProvider)));

final netWorthProvider = FutureProvider<NetWorthSnapshot>((ref) async {
  final db = ref.watch(databaseProvider);
  final service = ref.watch(netWorthServiceProvider);
  final accountRows = await db.select(db.accounts).get();
  final transactions = await db.transactionsDao.getAllForBalance();
  final liabilities = await db.select(db.liabilities).get();
  return service.compute(
    accounts: accountRows,
    transactions: transactions,
    liabilities: liabilities,
  );
});

final monthlyCashflowProvider = Provider<({double income, double expense})>((ref) {
  final txs = ref.watch(transactionsListProvider).valueOrNull ?? [];
  final now = DateTime.now();
  final from = AppDateUtils.startOfMonth(now);
  final to = AppDateUtils.endOfMonth(now);

  var income = 0.0;
  var expense = 0.0;
  for (final tx in txs) {
    if (tx.createdAt.isBefore(from) || tx.createdAt.isAfter(to)) continue;
    if (tx.transactionType == TransactionType.income) income += tx.amount;
    if (tx.transactionType == TransactionType.expense) expense += tx.amount;
  }
  return (income: income, expense: expense);
});

final recentTransactionsProvider = Provider<List<LedgerTransaction>>((ref) {
  final txs = ref.watch(transactionsListProvider).valueOrNull ?? [];
  return txs.take(8).toList();
});

final accountsSummaryProvider = Provider((ref) {
  return ref.watch(accountsListProvider).valueOrNull ?? [];
});

import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../../core/providers/core_providers.dart';
import '../../../../core/services/net_worth_service.dart';
import '../../../../core/utils/date_utils.dart';
import '../../../accounts/presentation/providers/account_providers.dart';
import '../../../transactions/domain/entities/ledger_transaction.dart';
import '../../../transactions/presentation/providers/transaction_providers.dart';
import '../../../../shared/domain/enums/transaction_type.dart';

final netWorthServiceProvider =
    Provider((ref) => NetWorthService(ref.watch(balanceCalculatorProvider)));

final netWorthProvider = FutureProvider<NetWorthSnapshot>((ref) async {
  final db = ref.watch(databaseProvider);
  final service = ref.watch(netWorthServiceProvider);
  final accountRows = await db.select(db.accounts).get();
  final transactions = await db.transactionsDao.getAllForBalance();
  final liabilities = await db.select(db.liabilities).get();
  return service.compute(
    accounts: accountRows,
    transactions: transactions,
    liabilities: liabilities,
  );
});

final monthlyCashflowProvider = Provider<({double income, double expense})>((ref) {
  final txs = ref.watch(transactionsListProvider).valueOrNull ?? [];
  final now = DateTime.now();
  final from = AppDateUtils.startOfMonth(now);
  final to = AppDateUtils.endOfMonth(now);

  var income = 0.0;
  var expense = 0.0;
  for (final tx in txs) {
    if (tx.createdAt.isBefore(from) || tx.createdAt.isAfter(to)) continue;
    if (tx.transactionType == TransactionType.income) income += tx.amount;
    if (tx.transactionType == TransactionType.expense) expense += tx.amount;
  }
  return (income: income, expense: expense);
});

final recentTransactionsProvider = Provider<List<LedgerTransaction>>((ref) {
  final txs = ref.watch(transactionsListProvider).valueOrNull ?? [];
  return txs.take(8).toList();
});

final accountsSummaryProvider = Provider((ref) {
  return ref.watch(accountsListProvider).valueOrNull ?? [];
});

// New: monthly series providers for charts
final _monthsCount = 6;

/// Returns a list of records for the last N months with expense totals.
final monthlyExpenseSeriesProvider = Provider<List<({DateTime month, double expense})>>((ref) {
  final txs = ref.watch(transactionsListProvider).valueOrNull ?? [];
  final now = DateTime.now();

  // initialize months map with zero values
  final months = <String, ({DateTime month, double expense})>{};
  for (var i = _monthsCount - 1; i >= 0; i--) {
    final dt = DateTime(now.year, now.month - i);
    final key = '${dt.year}-${dt.month}';
    months[key] = (month: dt, expense: 0.0);
  }

  for (final tx in txs) {
    if (tx.transactionType != TransactionType.expense) continue;
    final key = '${tx.createdAt.year}-${tx.createdAt.month}';
    if (months.containsKey(key)) {
      final existing = months[key]!;
      months[key] = (month: existing.month, expense: existing.expense + tx.amount);
    }
  }

  return months.values.toList();
});

final incomeVsExpenseSeriesProvider = Provider<List<({DateTime month, double income, double expense})>>((ref) {
  final txs = ref.watch(transactionsListProvider).valueOrNull ?? [];
  final now = DateTime.now();

  final months = <String, ({DateTime month, double income, double expense})>{};
  for (var i = _monthsCount - 1; i >= 0; i--) {
    final dt = DateTime(now.year, now.month - i);
    final key = '${dt.year}-${dt.month}';
    months[key] = (month: dt, income: 0.0, expense: 0.0);
  }

  for (final tx in txs) {
    final key = '${tx.createdAt.year}-${tx.createdAt.month}';
    if (!months.containsKey(key)) continue;
    final existing = months[key]!;
    var income = existing.income;
    var expense = existing.expense;
    if (tx.transactionType == TransactionType.income) income += tx.amount;
    if (tx.transactionType == TransactionType.expense) expense += tx.amount;
    months[key] = (month: existing.month, income: income, expense: expense);
  }

  return months.values.toList();
});

