    _emailCtrl = TextEditingController(text: widget.entry?.email ?? '');
    _passwordCtrl = TextEditingController(text: widget.entry?.password ?? '');
    _noteCtrl = TextEditingController(text: widget.entry?.note ?? '');
  }

