import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter/services.dart';
import 'package:wealthtracker/features/more/screens/add_password_screen.dart';
import '../../../shared/providers/passwords_provider.dart';
import '../../../shared/models/password_entry.dart';

class PasswordsScreen extends ConsumerStatefulWidget {
  const PasswordsScreen({super.key});

  @override
  ConsumerState<PasswordsScreen> createState() => _PasswordsScreenState();
}

class _PasswordsScreenState extends ConsumerState<PasswordsScreen> {
  final TextEditingController _searchCtrl = TextEditingController();
  String _query = '';
  bool _sortAz = true; // true: A-Z by appName, false: Z-A
  bool _showOnlyWithNote = false;

  @override
  void dispose() {
    _searchCtrl.dispose();
    super.dispose();
  }

  List<PasswordEntry> _applyFilters(List<PasswordEntry> src) {
    var list = src.where((e) {
      if (_showOnlyWithNote && (e.note == null || e.note!.trim().isEmpty)) return false;
      if (_query.trim().isEmpty) return true;
      final q = _query.toLowerCase();
      return e.appName.toLowerCase().contains(q) || e.username.toLowerCase().contains(q) || e.email.toLowerCase().contains(q) || (e.note ?? '').toLowerCase().contains(q);
    }).toList();
    list.sort((a, b) => _sortAz ? a.appName.toLowerCase().compareTo(b.appName.toLowerCase()) : b.appName.toLowerCase().compareTo(a.appName.toLowerCase()));
    return list;
  }

  Future<void> _showExportDialog(String title, String content) async {
    await showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(title),
        content: SizedBox(width: double.maxFinite, child: SingleChildScrollView(child: SelectableText(content))),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Close')),
          TextButton(
            onPressed: () {
              Clipboard.setData(ClipboardData(text: content));
              Navigator.pop(ctx);
              ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Copied to clipboard')));
            },
            child: const Text('Copy'),
          ),
        ],
      ),
    );
  }

  Future<void> _importDialog(bool json) async {
    final ctrl = TextEditingController();
    final ok = await showDialog<bool?>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Import ${json ? 'JSON' : 'CSV'}'),
        content: SizedBox(width: double.maxFinite, child: TextField(controller: ctrl, maxLines: 12, decoration: const InputDecoration(hintText: 'Paste content here'))),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          TextButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Import')),
        ],
      ),
    );
    if (ok == true && ctrl.text.trim().isNotEmpty) {
      try {
        if (json) {
          await ref.read(passwordsProvider.notifier).importJson(ctrl.text.trim());
        } else {
          await ref.read(passwordsProvider.notifier).importCsv(ctrl.text.trim());
        }
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Imported successfully')));
      } catch (e) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Import failed: $e')));
      }
    }
  }

  void _showDetailsSheet(PasswordEntry e) {
    bool obscure = true;
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      builder: (ctx) {
        return StatefulBuilder(builder: (ctx, setState) {
          return Padding(
            padding: MediaQuery.of(ctx).viewInsets.add(const EdgeInsets.all(16)),
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
              ListTile(
                title: Text(e.appName, style: Theme.of(context).textTheme.titleLarge),
                subtitle: Text(e.email.isNotEmpty ? e.email : e.username),
                trailing: IconButton(
                  icon: const Icon(Icons.copy),
                  onPressed: () {
                    Clipboard.setData(ClipboardData(text: e.email.isNotEmpty ? e.email : e.username));
                    Navigator.pop(ctx);
                    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Copied')));
                  },
                ),
              ),
              const SizedBox(height: 8),
              Row(children: [Text('Password:', style: Theme.of(context).textTheme.bodyLarge), const SizedBox(width: 8), Expanded(child: Text(obscure ? '••••••••' : e.password, style: const TextStyle(fontWeight: FontWeight.bold)))]),
              const SizedBox(height: 8),
              Row(children: [
                FilledButton.icon(
                  onPressed: () {
                    setState(() => obscure = !obscure);
                  },
                  icon: Icon(obscure ? Icons.visibility : Icons.visibility_off),
                  label: Text(obscure ? 'Reveal' : 'Hide'),
                ),
                const SizedBox(width: 8),
                FilledButton.icon(
                  onPressed: () {
                    Clipboard.setData(ClipboardData(text: e.password));
                    Navigator.pop(ctx);
                    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Password copied')));
                  },
                  icon: const Icon(Icons.copy),
                  label: const Text('Copy'),
                ),
                const SizedBox(width: 8),
                FilledButton.icon(
                  onPressed: () async {
                    await Navigator.of(context).push(MaterialPageRoute(builder: (_) => AddPasswordScreen(entry: e)));
                  },
                  icon: const Icon(Icons.edit),
                  label: const Text('Edit'),
                ),
                const Spacer(),
                TextButton(
                  onPressed: () async {
                    final confirmed = await showDialog<bool?>(context: context, builder: (dctx) => AlertDialog(title: const Text('Delete'), content: const Text('Delete this entry?'), actions: [TextButton(onPressed: () => Navigator.pop(dctx, false), child: const Text('Cancel')), TextButton(onPressed: () => Navigator.pop(dctx, true), child: const Text('Delete'))]));
                    if (confirmed == true) {
                      await ref.read(passwordsProvider.notifier).delete(e.id);
                      Navigator.pop(ctx);
                      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Entry deleted')));
                    }
                  },
                  child: const Text('Delete', style: TextStyle(color: Colors.red)),
                ),
              ]),
              const SizedBox(height: 12),
              if (e.note != null && e.note!.isNotEmpty) ...[
                Text('Note', style: Theme.of(context).textTheme.labelLarge),
                const SizedBox(height: 6),
                Text(e.note!),
                const SizedBox(height: 12),
              ],
            ]),
          );
        });
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final entries = ref.watch(passwordsProvider);
    final filtered = _applyFilters(entries);

    return Scaffold(
      appBar: AppBar(
        title: const Text('Passwords'),
        actions: [
          PopupMenuButton<String>(
            onSelected: (v) async {
              switch (v) {
                case 'export_json':
                  final s = await ref.read(passwordsProvider.notifier).exportJson();
                  await _showExportDialog('Export JSON', s);
                  break;
                case 'export_csv':
                  final s = await ref.read(passwordsProvider.notifier).exportCsv();
                  await _showExportDialog('Export CSV', s);
                  break;
                case 'import_json':
                  await _importDialog(true);
                  break;
                case 'import_csv':
                  await _importDialog(false);
                  break;
                case 'sort':
                  setState(() => _sortAz = !_sortAz);
                  break;
                case 'filter_note':
                  setState(() => _showOnlyWithNote = !_showOnlyWithNote);
                  break;
              }
            },
            itemBuilder: (ctx) => [
              const PopupMenuItem(value: 'export_json', child: Text('Export JSON')),
              const PopupMenuItem(value: 'export_csv', child: Text('Export CSV')),
              const PopupMenuItem(value: 'import_json', child: Text('Import JSON')),
              const PopupMenuItem(value: 'import_csv', child: Text('Import CSV')),
              PopupMenuItem(value: 'sort', child: Text(_sortAz ? 'Sort Z-A' : 'Sort A-Z')),
              PopupMenuItem(value: 'filter_note', child: Text(_showOnlyWithNote ? 'Show all' : 'Show only with notes')),
            ],
          ),
        ],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(12),
            child: TextField(
              controller: _searchCtrl,
              decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Search app, username, email, note', border: OutlineInputBorder()),
              onChanged: (v) => setState(() => _query = v),
            ),
          ),
          Expanded(
            child: filtered.isEmpty
                ? Center(child: Text('No passwords', style: Theme.of(context).textTheme.titleMedium))
                : ListView.separated(
                    padding: const EdgeInsets.all(16),
                    itemCount: filtered.length,
                    separatorBuilder: (_, __) => const SizedBox(height: 8),
                    itemBuilder: (context, index) {
                      final e = filtered[index];
                      return Card(
                        child: ListTile(
                          title: Text(e.appName),
                          subtitle: Text(e.email.isNotEmpty ? e.email : e.username),
                          trailing: IconButton(icon: const Icon(Icons.more_vert), onPressed: () => _showDetailsSheet(e)),
                          onTap: () => _showDetailsSheet(e),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () async {
          await Navigator.of(context).push(MaterialPageRoute(builder: (_) => const AddPasswordScreen()));
        },
        child: const Icon(Icons.add),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter/services.dart';
import 'package:wealthtracker/features/more/screens/add_password_screen.dart';
import '../../../shared/providers/passwords_provider.dart';
import '../../../shared/models/password_entry.dart';

class PasswordsScreen extends ConsumerStatefulWidget {
  const PasswordsScreen({super.key});

  @override
  ConsumerState<PasswordsScreen> createState() => _PasswordsScreenState();
}

class _PasswordsScreenState extends ConsumerState<PasswordsScreen> {
  final TextEditingController _searchCtrl = TextEditingController();
  String _query = '';
  bool _sortAz = true; // true: A-Z by appName, false: Z-A
  bool _showOnlyWithNote = false;

  @override
  void dispose() {
    _searchCtrl.dispose();
    super.dispose();
  }

  List<PasswordEntry> _applyFilters(List<PasswordEntry> src) {
    var list = src.where((e) {
      if (_showOnlyWithNote && (e.note == null || e.note!.trim().isEmpty)) return false;
      if (_query.trim().isEmpty) return true;
      final q = _query.toLowerCase();
      return e.appName.toLowerCase().contains(q) || e.username.toLowerCase().contains(q) || e.email.toLowerCase().contains(q) || (e.note ?? '').toLowerCase().contains(q);
    }).toList();
    list.sort((a, b) => _sortAz ? a.appName.toLowerCase().compareTo(b.appName.toLowerCase()) : b.appName.toLowerCase().compareTo(a.appName.toLowerCase()));
    return list;
  }

  Future<void> _showExportDialog(String title, String content) async {
    await showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(title),
        content: SizedBox(width: double.maxFinite, child: SingleChildScrollView(child: SelectableText(content))),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Close')),
          TextButton(
            onPressed: () {
              Clipboard.setData(ClipboardData(text: content));
              Navigator.pop(ctx);
              ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Copied to clipboard')));
            },
            child: const Text('Copy'),
          ),
        ],
      ),
    );
  }

  Future<void> _importDialog(bool json) async {
    final ctrl = TextEditingController();
    final ok = await showDialog<bool?>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Import ${json ? 'JSON' : 'CSV'}'),
        content: SizedBox(width: double.maxFinite, child: TextField(controller: ctrl, maxLines: 12, decoration: const InputDecoration(hintText: 'Paste content here'))),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          TextButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Import')),
        ],
      ),
    );
    if (ok == true && ctrl.text.trim().isNotEmpty) {
      try {
        if (json) {
          await ref.read(passwordsProvider.notifier).importJson(ctrl.text.trim());
        } else {
          await ref.read(passwordsProvider.notifier).importCsv(ctrl.text.trim());
        }
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Imported successfully')));
      } catch (e) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Import failed: $e')));
      }
    }
  }

  void _showDetailsSheet(PasswordEntry e) {
    bool obscure = true;
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      builder: (ctx) {
        return StatefulBuilder(builder: (ctx, setState) {
          return Padding(
            padding: MediaQuery.of(ctx).viewInsets.add(const EdgeInsets.all(16)),
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
              ListTile(
                title: Text(e.appName, style: Theme.of(context).textTheme.titleLarge),
                subtitle: Text(e.email.isNotEmpty ? e.email : e.username),
                trailing: IconButton(
                  icon: const Icon(Icons.copy),
                  onPressed: () {
                    Clipboard.setData(ClipboardData(text: e.email.isNotEmpty ? e.email : e.username));
                    Navigator.pop(ctx);
                    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Copied')));
                  },
                ),
              ),
              const SizedBox(height: 8),
              Row(children: [Text('Password:', style: Theme.of(context).textTheme.bodyLarge), const SizedBox(width: 8), Expanded(child: Text(obscure ? '••••••••' : e.password, style: const TextStyle(fontWeight: FontWeight.bold)))]),
              const SizedBox(height: 8),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                alignment: WrapAlignment.start,
                children: [
                  FilledButton.icon(
                    onPressed: () {
                      setState(() => obscure = !obscure);
                    },
                    icon: Icon(obscure ? Icons.visibility : Icons.visibility_off),
                    label: Text(obscure ? 'Reveal' : 'Hide'),
                  ),
                  FilledButton.icon(
                    onPressed: () {
                      Clipboard.setData(ClipboardData(text: e.password));
                      Navigator.pop(ctx);
                      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Password copied')));
                    },
                    icon: const Icon(Icons.copy),
                    label: const Text('Copy'),
                  ),
                  FilledButton.icon(
                    onPressed: () async {
                      await Navigator.of(context).push(MaterialPageRoute(builder: (_) => AddPasswordScreen(entry: e)));
                    },
                    icon: const Icon(Icons.edit),
                    label: const Text('Edit'),
                  ),
                  TextButton(
                    onPressed: () async {
                      final confirmed = await showDialog<bool?>(context: context, builder: (dctx) => AlertDialog(title: const Text('Delete'), content: const Text('Delete this entry?'), actions: [TextButton(onPressed: () => Navigator.pop(dctx, false), child: const Text('Cancel')), TextButton(onPressed: () => Navigator.pop(dctx, true), child: const Text('Delete'))]));
                      if (confirmed == true) {
                        await ref.read(passwordsProvider.notifier).delete(e.id);
                        Navigator.pop(ctx);
                        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Entry deleted')));
                      }
                    },
                    child: const Text('Delete', style: TextStyle(color: Colors.red)),
                  ),
                ],
              ),
              const SizedBox(height: 12),
              if (e.note != null && e.note!.isNotEmpty) ...[
                Text('Note', style: Theme.of(context).textTheme.labelLarge),
                const SizedBox(height: 6),
                Text(e.note!),
                const SizedBox(height: 12),
              ],
            ]),
          );
        });
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final entries = ref.watch(passwordsProvider);
    final filtered = _applyFilters(entries);

    return Scaffold(
      appBar: AppBar(
        title: const Text('Passwords'),
        actions: [
          PopupMenuButton<String>(
            onSelected: (v) async {
              switch (v) {
                case 'export_json':
                  final s = await ref.read(passwordsProvider.notifier).exportJson();
                  await _showExportDialog('Export JSON', s);
                  break;
                case 'export_csv':
                  final s = await ref.read(passwordsProvider.notifier).exportCsv();
                  await _showExportDialog('Export CSV', s);
                  break;
                case 'import_json':
                  await _importDialog(true);
                  break;
                case 'import_csv':
                  await _importDialog(false);
                  break;
                case 'sort':
                  setState(() => _sortAz = !_sortAz);
                  break;
                case 'filter_note':
                  setState(() => _showOnlyWithNote = !_showOnlyWithNote);
                  break;
              }
            },
            itemBuilder: (ctx) => [
              const PopupMenuItem(value: 'export_json', child: Text('Export JSON')),
              const PopupMenuItem(value: 'export_csv', child: Text('Export CSV')),
              const PopupMenuItem(value: 'import_json', child: Text('Import JSON')),
              const PopupMenuItem(value: 'import_csv', child: Text('Import CSV')),
              PopupMenuItem(value: 'sort', child: Text(_sortAz ? 'Sort Z-A' : 'Sort A-Z')),
              PopupMenuItem(value: 'filter_note', child: Text(_showOnlyWithNote ? 'Show all' : 'Show only with notes')),
            ],
          ),
        ],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(12),
            child: TextField(
              controller: _searchCtrl,
              decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Search app, username, email, note', border: OutlineInputBorder()),
              onChanged: (v) => setState(() => _query = v),
            ),
          ),
          Expanded(
            child: filtered.isEmpty
                ? Center(child: Text('No passwords', style: Theme.of(context).textTheme.titleMedium))
                : ListView.separated(
                    padding: const EdgeInsets.all(16),
                    itemCount: filtered.length,
                    separatorBuilder: (_, __) => const SizedBox(height: 8),
                    itemBuilder: (context, index) {
                      final e = filtered[index];
                      return Card(
                        child: ListTile(
                          title: Text(e.appName),
                          subtitle: Text(e.email.isNotEmpty ? e.email : e.username),
                          trailing: IconButton(icon: const Icon(Icons.more_vert), onPressed: () => _showDetailsSheet(e)),
                          onTap: () => _showDetailsSheet(e),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () async {
          await Navigator.of(context).push(MaterialPageRoute(builder: (_) => const AddPasswordScreen()));
        },
        child: const Icon(Icons.add),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:intl/intl.dart';
import '../../../../shared/models/portfolio.dart';
import '../../../../shared/providers/portfolio_provider.dart';
import '../../../../shared/providers/transaction_provider.dart';

class DividendDetailScreen extends ConsumerWidget {
  final Dividend dividend;
  const DividendDetailScreen({super.key, required this.dividend});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final currencyFormat = NumberFormat.currency(symbol: 'Rs ', decimalDigits: 2);
    // compute number of shares from totalReceived / amountPerShare (guard divide-by-zero)
    final shares = dividend.amountPerShare > 0 ? dividend.totalReceived / dividend.amountPerShare : 0.0;
    final sharesFormat = NumberFormat('#,##0.####');

    return Scaffold(
      appBar: AppBar(
        title: Text('${dividend.companyName}'),
        actions: [
          PopupMenuButton<String>(
            onSelected: (v) => _handleDeleteAction(context, ref, dividend, v),
            itemBuilder: (ctx) => [
              const PopupMenuItem(value: 'delete', child: Text('Delete')),
              const PopupMenuItem(value: 'reverse', child: Text('Delete & Reverse Cash')),
            ],
          ),
        ],
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Card(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
          child: Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                ListTile(
                  contentPadding: EdgeInsets.zero,
                  leading: const Icon(Icons.business_outlined),
                  title: Text('${dividend.companyName} (${dividend.symbol})', style: Theme.of(context).textTheme.titleLarge),
                  subtitle: Text('Recorded on ${DateFormat.yMMMd().format(dividend.date)}'),
                ),
                const SizedBox(height: 12),
                Row(
                  children: [
                    Text('Amount per share:', style: Theme.of(context).textTheme.bodyLarge),
                    const SizedBox(width: 8),
                    Text('Rs ${dividend.amountPerShare.toStringAsFixed(2)}', style: const TextStyle(fontWeight: FontWeight.bold)),
                  ],
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Text('Shares:', style: Theme.of(context).textTheme.bodyLarge),
                    const SizedBox(width: 8),
                    Text(sharesFormat.format(shares), style: const TextStyle(fontWeight: FontWeight.bold)),
                  ],
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Text('Total received:', style: Theme.of(context).textTheme.bodyLarge),
                    const SizedBox(width: 8),
                    Text(currencyFormat.format(dividend.totalReceived), style: const TextStyle(fontWeight: FontWeight.bold, color: Colors.green)),
                  ],
                ),
                const SizedBox(height: 12),
                if (dividend.transactionId != null) ...[
                  Text('Linked transaction', style: Theme.of(context).textTheme.labelLarge),
                  const SizedBox(height: 8),
                  Text('Transaction ID: ${dividend.transactionId}'),
                  const SizedBox(height: 12),
                ],

                // Optional actions
                const SizedBox(height: 8),
                Text('Notes', style: Theme.of(context).textTheme.labelLarge),
                const SizedBox(height: 6),
                Text('No additional notes.'),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _handleDeleteAction(BuildContext context, WidgetRef ref, Dividend dividend, String action) async {
    if (action != 'delete' && action != 'reverse') return;

    final result = await showDialog<String?>(
      context: context,
      builder: (ctx) {
        return AlertDialog(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
          title: const Text('Delete Dividend'),
          content: const Text('Are you sure you want to delete this dividend?'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx, 'cancel'), child: const Text('Cancel')),
            TextButton(onPressed: () => Navigator.pop(ctx, 'confirm'), child: const Text('Delete')),
          ],
        );
      },
    );

    if (result != 'confirm') return;

    if (action == 'delete') {
      ref.read(dividendProvider.notifier).deleteDividend(dividend.id);
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('️ Dividend record deleted')));
      Navigator.of(context).pop();
      return;
    }

    final amount = dividend.totalReceived;
    final currentCashBalance = ref.read(portfolioCashProvider);
    if (currentCashBalance < amount) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('⚠️ Insufficient cash available to reverse payout')));
      return;
    }

    await ref.read(portfolioTransferProvider.notifier).withdrawFromPortfolio(
      amount,
      note: 'Reversal for deleted dividend: ${dividend.companyName}',
    );

    if (dividend.transactionId != null) {
      ref.read(transactionProvider.notifier).deleteTransaction(dividend.transactionId!);
    }

    ref.read(dividendProvider.notifier).deleteDividend(dividend.id);
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text(' Payout deleted and balance reversed')));
    Navigator.of(context).pop();
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:intl/intl.dart';
import '../../../../shared/models/portfolio.dart';
import '../../../../shared/providers/portfolio_provider.dart';
import '../../../../shared/providers/transaction_provider.dart';

class DividendDetailScreen extends ConsumerWidget {
  final Dividend dividend;
  const DividendDetailScreen({super.key, required this.dividend});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final currencyFormat = NumberFormat.currency(symbol: 'Rs ', decimalDigits: 2);
    // compute number of shares from totalReceived / amountPerShare (guard divide-by-zero)
    final shares = dividend.amountPerShare > 0 ? dividend.totalReceived / dividend.amountPerShare : 0.0;
    final sharesFormat = NumberFormat('#,##0.####');
    // Try to resolve linked transaction to display notes (but do not show transaction ID)
    final linkedTxn = dividend.transactionId != null ? ref.read(transactionProvider.notifier).getTransactionById(dividend.transactionId!) : null;

    return Scaffold(
      appBar: AppBar(
        title: Text('${dividend.companyName}'),
        actions: [
          PopupMenuButton<String>(
            onSelected: (v) => _handleDeleteAction(context, ref, dividend, v),
            itemBuilder: (ctx) => [
              const PopupMenuItem(value: 'delete', child: Text('Delete')),
              const PopupMenuItem(value: 'reverse', child: Text('Delete & Reverse Cash')),
            ],
          ),
        ],
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Card(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
          child: Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                ListTile(
                  contentPadding: EdgeInsets.zero,
                  leading: const Icon(Icons.business_outlined),
                  title: Text('${dividend.companyName} (${dividend.symbol})', style: Theme.of(context).textTheme.titleLarge),
                  subtitle: Text('Recorded on ${DateFormat.yMMMd().format(dividend.date)}'),
                ),
                const SizedBox(height: 12),
                Row(
                  children: [
                    Text('Amount per share:', style: Theme.of(context).textTheme.bodyLarge),
                    const SizedBox(width: 8),
                    Text('Rs ${dividend.amountPerShare.toStringAsFixed(2)}', style: const TextStyle(fontWeight: FontWeight.bold)),
                  ],
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Text('Shares:', style: Theme.of(context).textTheme.bodyLarge),
                    const SizedBox(width: 8),
                    Text(sharesFormat.format(shares), style: const TextStyle(fontWeight: FontWeight.bold)),
                  ],
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Text('Total received:', style: Theme.of(context).textTheme.bodyLarge),
                    const SizedBox(width: 8),
                    Text(currencyFormat.format(dividend.totalReceived), style: const TextStyle(fontWeight: FontWeight.bold, color: Colors.green)),
                  ],
                ),
                const SizedBox(height: 12),
                // Show notes from linked transaction if available; otherwise don't show a notes block
                if (linkedTxn != null && (linkedTxn.notes != null && linkedTxn.notes!.trim().isNotEmpty)) ...[
                  Text('Notes', style: Theme.of(context).textTheme.labelLarge),
                  const SizedBox(height: 6),
                  Text(linkedTxn.notes!),
                ],
              ],
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _handleDeleteAction(BuildContext context, WidgetRef ref, Dividend dividend, String action) async {
    if (action != 'delete' && action != 'reverse') return;

    final result = await showDialog<String?>(
      context: context,
      builder: (ctx) {
        return AlertDialog(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
          title: const Text('Delete Dividend'),
          content: const Text('Are you sure you want to delete this dividend?'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx, 'cancel'), child: const Text('Cancel')),
            TextButton(onPressed: () => Navigator.pop(ctx, 'confirm'), child: const Text('Delete')),
          ],
        );
      },
    );

    if (result != 'confirm') return;

    if (action == 'delete') {
      ref.read(dividendProvider.notifier).deleteDividend(dividend.id);
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('️ Dividend record deleted')));
      Navigator.of(context).pop();
      return;
    }

    final amount = dividend.totalReceived;
    final currentCashBalance = ref.read(portfolioCashProvider);
    if (currentCashBalance < amount) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('⚠️ Insufficient cash available to reverse payout')));
      return;
    }

    await ref.read(portfolioTransferProvider.notifier).withdrawFromPortfolio(
      amount,
      note: 'Reversal for deleted dividend: ${dividend.companyName}',
    );

    if (dividend.transactionId != null) {
      ref.read(transactionProvider.notifier).deleteTransaction(dividend.transactionId!);
    }

    ref.read(dividendProvider.notifier).deleteDividend(dividend.id);
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text(' Payout deleted and balance reversed')));
    Navigator.of(context).pop();
  }
}

