            ),
            const SizedBox(height: 16),
            // Price charts
            Text('Price history', style: Theme.of(context).textTheme.titleMedium),
            const SizedBox(height: 8),
            priceHistory.isEmpty
                ? const Text('No price history available')
                : SizedBox(
                    height: 200,
