                  );
                  if (res != null) {
                    final pp = PricePoint(time: DateTime.now(), price: res);
                    ref.read(priceHistoryProvider.notifier).addPricePoint(symbol, pp);
                  }
                },
              ),
            ),
            const SizedBox(height: 16),
