            const SizedBox(height: 8),
            transactions.isEmpty
                ? const Text('No transactions for this holding')
                : Column(
                    children: transactions.reversed.map((t) {
                      return Card(
                        margin: const EdgeInsets.only(bottom: 8),
                        child: ListTile(
