import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:intl/intl.dart';
import '../../../shared/providers/portfolio_provider.dart';
import 'package:wealthtracker/shared/models/portfolio.dart' as pmodel;
import '../../../shared/models/portfolio.dart' as models;

class PortfolioTransactionsScreen extends ConsumerWidget {
  const PortfolioTransactionsScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final stockTransactions = ref.watch(stockTransactionProvider);
    final dividends = ref.watch(dividendProvider);

    // Merge stock transactions and dividends into a single list sorted by date desc
    final List<_TimelineItem> combined = [];
    for (final s in stockTransactions) {
      combined.add(_TimelineItem(kind: 'stock', date: s.date, data: s));
    }
    for (final d in dividends) {
      combined.add(_TimelineItem(kind: 'dividend', date: d.date, data: d));
    }
    combined.sort((a, b) => b.date.compareTo(a.date));

    final currencyFormat = NumberFormat.currency(symbol: 'Rs ', decimalDigits: 2);

    return Scaffold(
      appBar: AppBar(title: const Text('Stock Transactions')),
      body: combined.isEmpty
          ? const Center(child: Text('No transactions'))
          : ListView.builder(
              padding: const EdgeInsets.all(16),
              itemCount: combined.length,
              itemBuilder: (context, index) {
                final item = combined[index];
                if (item.kind == 'stock') {
                  final txn = item.data as pmodel.StockTransaction;
                  final isBuy = txn.type == pmodel.StockTransactionType.buy;
                  return Card(
                    margin: const EdgeInsets.only(bottom: 12),
                    child: ListTile(
                      leading: CircleAvatar(
                        backgroundColor: isBuy ? Colors.green.shade100 : Colors.red.shade100,
                        child: Icon(isBuy ? Icons.add : Icons.remove, color: isBuy ? Colors.green : Colors.red),
                      ),
                      title: Text('${isBuy ? 'BUY' : 'SELL'} ${txn.symbol}'),
                      subtitle: Text('${txn.quantity} shares @ ${currencyFormat.format(txn.price)}\n${DateFormat.yMMMd().format(txn.date)}'),
                      trailing: Text(
                        currencyFormat.format(txn.total),
                        style: TextStyle(color: isBuy ? Colors.red : Colors.green, fontWeight: FontWeight.bold),
                      ),
                      isThreeLine: true,
                    ),
                  );
                } else {
                  final d = item.data as models.Dividend;
                  return Card(
                    margin: const EdgeInsets.only(bottom: 12),
                    child: ListTile(
                      leading: const CircleAvatar(
                        backgroundColor: Colors.green,
                        child: Icon(Icons.monetization_on, color: Colors.white),
                      ),
                      title: Text('DIVIDEND ${d.symbol}'),
                      subtitle: Text('${d.companyName} — ${d.amountPerShare.toStringAsFixed(2)} per share\n${DateFormat.yMMMd().format(d.date)}'),
                      trailing: Text(currencyFormat.format(d.totalReceived), style: const TextStyle(color: Colors.green, fontWeight: FontWeight.bold)),
                      isThreeLine: true,
                    ),
                  );
                }
              },
            ),
    );
  }
}

class _TimelineItem {
  final String kind; // 'stock' or 'dividend'
  final DateTime date;
  final Object data;
  _TimelineItem({required this.kind, required this.date, required this.data});
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../../core/providers/core_providers.dart';
import '../../../../core/utils/date_utils.dart';
import '../../../../shared/domain/enums/account_type.dart';
import '../../../../shared/domain/enums/enums.dart';
import '../../../accounts/domain/entities/account_entity.dart';
import '../../../accounts/presentation/providers/account_providers.dart';
import '../../../../shared/domain/enums/category_type.dart';
import '../../../categories/presentation/providers/category_providers.dart';
import '../../domain/entities/ledger_transaction.dart';
import '../../domain/services/transaction_ledger_service.dart';
import '../providers/transaction_providers.dart';

class TransactionFormScreen extends ConsumerStatefulWidget {
  const TransactionFormScreen({
    super.key,
    this.transactionId,
    this.preselectedAccountId,
  });

  final String? transactionId;
  final String? preselectedAccountId;

  @override
  ConsumerState<TransactionFormScreen> createState() => _TransactionFormScreenState();
}

class _TransactionFormScreenState extends ConsumerState<TransactionFormScreen> {
  final _formKey = GlobalKey<FormState>();
  final _amountController = TextEditingController();
  final _notesController = TextEditingController();

  TransactionType _transactionType = TransactionType.expense;
  String? _sourceId;
  String? _destinationId;
  String? _categoryId;
  DateTime _transactionDate = DateTime.now();
  bool _loading = false;
  bool _initialized = false;

  bool get _isEdit => widget.transactionId != null;

  @override
  void dispose() {
    _amountController.dispose();
    _notesController.dispose();
    super.dispose();
  }

  void _applyTypeDefaults(List<AccountEntity> accounts) {
    switch (_transactionType) {
      case TransactionType.income:
      case TransactionType.dividend:
        _sourceId = null;
        _destinationId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
      case TransactionType.expense:
      case TransactionType.liabilityPayment:
        _destinationId = null;
        _sourceId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
      case TransactionType.transfer:
        _sourceId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
        _destinationId ??= _secondAccountId(accounts, _sourceId);
      case TransactionType.investmentFunding:
        _sourceId ??= _firstNonInvestmentAccount(accounts);
        _destinationId ??= _firstInvestmentAccount(accounts);
    }
  }

  String? _firstAccountId(List<AccountEntity> accounts) =>
      accounts.isNotEmpty ? accounts.first.id : null;

  String? _secondAccountId(List<AccountEntity> accounts, String? exclude) {
    final other = accounts.where((a) => a.id != exclude);
    return other.isNotEmpty ? other.first.id : null;
  }

  String? _firstInvestmentAccount(List<AccountEntity> accounts) {
    final list = accounts.where((a) => a.accountType == AccountType.investment);
    return list.isNotEmpty ? list.first.id : null;
  }

  String? _firstNonInvestmentAccount(List<AccountEntity> accounts) {
    final list = accounts.where((a) => a.accountType != AccountType.investment);
    return list.isNotEmpty ? list.first.id : null;
  }

  Future<void> _loadExisting() async {
    final tx = await ref.read(transactionRepositoryProvider).getById(widget.transactionId!);
    if (tx == null || !mounted) return;
    _amountController.text = tx.amount.toString();
    _notesController.text = tx.notes;
    setState(() {
      _transactionType = tx.transactionType;
      _sourceId = tx.sourceAccountId;
      _destinationId = tx.destinationAccountId;
      _categoryId = tx.categoryId;
      _transactionDate = tx.createdAt;
      _initialized = true;
    });
  }

  Future<void> _pickDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _transactionDate,
      firstDate: DateTime(2000),
      lastDate: DateTime.now().add(const Duration(days: 365)),
    );
    if (picked != null) {
      setState(() => _transactionDate = picked);
    }
  }

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _loading = true);

    final amount = double.parse(_amountController.text);
    final idGen = ref.read(idGeneratorProvider);
    final now = DateTime.now();

    final tx = LedgerTransaction(
      id: _isEdit ? widget.transactionId! : idGen.newId(),
      transactionType: _transactionType,
      sourceAccountId: _sourceId,
      destinationAccountId: _destinationId,
      categoryId: _categoryId,
      amount: amount,
      notes: _notesController.text.trim(),
      createdAt: _isEdit
          ? (await ref.read(transactionRepositoryProvider).getById(widget.transactionId!))!
              .createdAt
          : DateTime(
              _transactionDate.year,
              _transactionDate.month,
              _transactionDate.day,
              now.hour,
              now.minute,
            ),
      updatedAt: now,
    );

    try {
      if (_isEdit) {
        await ref.read(updateTransactionProvider)(tx);
      } else {
        await ref.read(createTransactionProvider)(tx);
      }
      if (mounted) context.pop();
    } on TransactionValidationException catch (e) {
      _showError(e.message);
    } catch (e) {
      _showError(e.toString());
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _showError(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
  }

  List<AccountEntity> _destinationAccounts(List<AccountEntity> all) {
    if (_transactionType == TransactionType.investmentFunding) {
      return all.where((a) => a.accountType == AccountType.investment).toList();
    }
    return all;
  }

  List<AccountEntity> _sourceAccounts(List<AccountEntity> all) {
    if (_transactionType == TransactionType.investmentFunding) {
      return all.where((a) => a.accountType != AccountType.investment).toList();
    }
    return all;
  }

  @override
  Widget build(BuildContext context) {
    final accounts = ref.watch(accountsListProvider).valueOrNull ?? [];
    final categories = ref.watch(categoriesListProvider).valueOrNull ?? [];

    if (_isEdit && !_initialized) {
      _loadExisting();
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    if (!_isEdit && !_initialized && accounts.isNotEmpty) {
      _applyTypeDefaults(accounts);
      _initialized = true;
    }

    final filteredCategories = categories.where((c) {
      return switch (_transactionType) {
        TransactionType.income => c.type == CategoryType.income,
        TransactionType.expense ||
        TransactionType.liabilityPayment =>
          c.type == CategoryType.expense,
        TransactionType.investmentFunding => c.type == CategoryType.investment,
        _ => true,
      };
    }).toList();

    return Scaffold(
      appBar: AppBar(title: Text(_isEdit ? 'Edit transaction' : 'New transaction')),
      body: Form(
        key: _formKey,
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            DropdownButtonFormField<TransactionType>(
              initialValue: _transactionType,
              decoration: const InputDecoration(labelText: 'Transaction type'),
              items: TransactionType.values
                  .map((t) => DropdownMenuItem(value: t, child: Text(t.label)))
                  .toList(),
              onChanged: (v) {
                setState(() {
                  _transactionType = v ?? _transactionType;
                  _applyTypeDefaults(accounts);
                });
              },
            ),
            const SizedBox(height: 16),
            if (_transactionType.requiresSource) ...[
              DropdownButtonFormField<String>(
                initialValue: _sourceId,
                decoration: const InputDecoration(labelText: 'Source account'),
                items: _sourceAccounts(accounts)
                    .map((a) => DropdownMenuItem(value: a.id, child: Text(a.name)))
                    .toList(),
                onChanged: (v) => setState(() => _sourceId = v),
                validator: (v) => v == null ? 'Select source account' : null,
              ),
              const SizedBox(height: 16),
            ],
            if (_transactionType.requiresDestination) ...[
              DropdownButtonFormField<String>(
                initialValue: _destinationId,
                decoration: InputDecoration(
                  labelText: _transactionType == TransactionType.investmentFunding
                      ? 'Investment funding account'
                      : 'Destination account',
                ),
                items: _destinationAccounts(accounts)
                    .map((a) => DropdownMenuItem(value: a.id, child: Text(a.name)))
                    .toList(),
                onChanged: (v) => setState(() => _destinationId = v),
                validator: (v) => v == null ? 'Select destination account' : null,
              ),
              const SizedBox(height: 16),
            ],
            if (filteredCategories.isNotEmpty)
              DropdownButtonFormField<String?>(
                initialValue: _categoryId,
                decoration: const InputDecoration(labelText: 'Category (optional)'),
                items: [
                  const DropdownMenuItem(value: null, child: Text('None')),
                  ...filteredCategories.map(
                    (c) => DropdownMenuItem(value: c.id, child: Text(c.name)),
                  ),
                ],
                onChanged: (v) => setState(() => _categoryId = v),
              ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _amountController,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(labelText: 'Amount (PKR)'),
              validator: (v) {
                final n = double.tryParse(v ?? '');
                if (n == null || n <= 0) return 'Enter a valid amount';
                return null;
              },
            ),
            const SizedBox(height: 16),
            ListTile(
              contentPadding: EdgeInsets.zero,
              title: const Text('Date'),
              subtitle: Text(AppDateUtils.formatDate(_transactionDate)),
              trailing: IconButton(
                icon: const Icon(Icons.calendar_today),
                onPressed: _isEdit ? null : _pickDate,
              ),
            ),
            const SizedBox(height: 8),
            TextFormField(
              controller: _notesController,
              decoration: const InputDecoration(labelText: 'Notes'),
              maxLines: 3,
            ),
            const SizedBox(height: 32),
            FilledButton(
              onPressed: _loading ? null : _save,
              child: _loading
                  ? const SizedBox(
                      height: 22,
                      width: 22,
                      child: CircularProgressIndicator(strokeWidth: 2),
                    )
                  : Text(_isEdit ? 'Save changes' : 'Save transaction'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../../core/providers/core_providers.dart';
import '../../../../core/utils/date_utils.dart';
import '../../../../shared/domain/enums/account_type.dart';
import '../../../../shared/domain/enums/enums.dart';
import '../../../accounts/domain/entities/account_entity.dart';
import '../../../accounts/presentation/providers/account_providers.dart';
import '../../../../shared/domain/enums/category_type.dart';
import '../../../categories/presentation/providers/category_providers.dart';
import '../../domain/entities/ledger_transaction.dart';
import '../../domain/services/transaction_ledger_service.dart';
import '../providers/transaction_providers.dart';
import 'package:cursor_bhai/features/dashboard/presentation/providers/dashboard_providers.dart';

class TransactionFormScreen extends ConsumerStatefulWidget {
  const TransactionFormScreen({
    super.key,
    this.transactionId,
    this.preselectedAccountId,
  });

  final String? transactionId;
  final String? preselectedAccountId;

  @override
  ConsumerState<TransactionFormScreen> createState() => _TransactionFormScreenState();
}

class _TransactionFormScreenState extends ConsumerState<TransactionFormScreen> {
  final _formKey = GlobalKey<FormState>();
  final _amountController = TextEditingController();
  final _notesController = TextEditingController();

  TransactionType _transactionType = TransactionType.expense;
  String? _sourceId;
  String? _destinationId;
  String? _categoryId;
  DateTime _transactionDate = DateTime.now();
  bool _loading = false;
  bool _initialized = false;

  bool get _isEdit => widget.transactionId != null;

  @override
  void dispose() {
    _amountController.dispose();
    _notesController.dispose();
    super.dispose();
  }

  void _applyTypeDefaults(List<AccountEntity> accounts) {
    switch (_transactionType) {
      case TransactionType.income:
      case TransactionType.dividend:
        _sourceId = null;
        _destinationId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
      case TransactionType.expense:
      case TransactionType.liabilityPayment:
        _destinationId = null;
        _sourceId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
      case TransactionType.transfer:
        _sourceId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
        _destinationId ??= _secondAccountId(accounts, _sourceId);
      case TransactionType.investmentFunding:
        _sourceId ??= _firstNonInvestmentAccount(accounts);
        _destinationId ??= _firstInvestmentAccount(accounts);
    }
  }

  String? _firstAccountId(List<AccountEntity> accounts) =>
      accounts.isNotEmpty ? accounts.first.id : null;

  String? _secondAccountId(List<AccountEntity> accounts, String? exclude) {
    final other = accounts.where((a) => a.id != exclude);
    return other.isNotEmpty ? other.first.id : null;
  }

  String? _firstInvestmentAccount(List<AccountEntity> accounts) {
    final list = accounts.where((a) => a.accountType == AccountType.investment);
    return list.isNotEmpty ? list.first.id : null;
  }

  String? _firstNonInvestmentAccount(List<AccountEntity> accounts) {
    final list = accounts.where((a) => a.accountType != AccountType.investment);
    return list.isNotEmpty ? list.first.id : null;
  }

  Future<void> _loadExisting() async {
    final tx = await ref.read(transactionRepositoryProvider).getById(widget.transactionId!);
    if (tx == null || !mounted) return;
    _amountController.text = tx.amount.toString();
    _notesController.text = tx.notes;
    setState(() {
      _transactionType = tx.transactionType;
      _sourceId = tx.sourceAccountId;
      _destinationId = tx.destinationAccountId;
      _categoryId = tx.categoryId;
      _transactionDate = tx.createdAt;
      _initialized = true;
    });
  }

  Future<void> _pickDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _transactionDate,
      firstDate: DateTime(2000),
      lastDate: DateTime.now().add(const Duration(days: 365)),
    );
    if (picked != null) {
      setState(() => _transactionDate = picked);
    }
  }

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _loading = true);

    final amount = double.parse(_amountController.text);
    final idGen = ref.read(idGeneratorProvider);
    final now = DateTime.now();

    final tx = LedgerTransaction(
      id: _isEdit ? widget.transactionId! : idGen.newId(),
      transactionType: _transactionType,
      sourceAccountId: _sourceId,
      destinationAccountId: _destinationId,
      categoryId: _categoryId,
      amount: amount,
      notes: _notesController.text.trim(),
      createdAt: _isEdit
          ? (await ref.read(transactionRepositoryProvider).getById(widget.transactionId!))!
              .createdAt
          : DateTime(
              _transactionDate.year,
              _transactionDate.month,
              _transactionDate.day,
              now.hour,
              now.minute,
            ),
      updatedAt: now,
    );

    try {
      if (_isEdit) {
        await ref.read(updateTransactionProvider)(tx);
      } else {
        await ref.read(createTransactionProvider)(tx);
      }
      // Refresh related providers so UI (accounts, net worth, lists) updates immediately
      ref.invalidate(transactionsListProvider);
      ref.invalidate(accountsListProvider);
      ref.invalidate(netWorthProvider);

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(_isEdit ? 'Transaction updated' : 'Transaction created')),
        );
        await Future.delayed(const Duration(milliseconds: 300));
        context.pop();
      }
    } on TransactionValidationException catch (e) {
      _showError(e.message);
    } catch (e) {
      _showError(e.toString());
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _showError(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
  }

  List<AccountEntity> _destinationAccounts(List<AccountEntity> all) {
    if (_transactionType == TransactionType.investmentFunding) {
      return all.where((a) => a.accountType == AccountType.investment).toList();
    }
    return all;
  }

  List<AccountEntity> _sourceAccounts(List<AccountEntity> all) {
    if (_transactionType == TransactionType.investmentFunding) {
      return all.where((a) => a.accountType != AccountType.investment).toList();
    }
    return all;
  }

  @override
  Widget build(BuildContext context) {
    final accounts = ref.watch(accountsListProvider).valueOrNull ?? [];
    final categories = ref.watch(categoriesListProvider).valueOrNull ?? [];

    if (_isEdit && !_initialized) {
      _loadExisting();
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    if (!_isEdit && !_initialized && accounts.isNotEmpty) {
      _applyTypeDefaults(accounts);
      _initialized = true;
    }

    final filteredCategories = categories.where((c) {
      return switch (_transactionType) {
        TransactionType.income => c.type == CategoryType.income,
        TransactionType.expense ||
        TransactionType.liabilityPayment =>
          c.type == CategoryType.expense,
        TransactionType.investmentFunding => c.type == CategoryType.investment,
        _ => true,
      };
    }).toList();

    return Scaffold(
      appBar: AppBar(title: Text(_isEdit ? 'Edit transaction' : 'New transaction')),
      body: Form(
        key: _formKey,
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            DropdownButtonFormField<TransactionType>(
              initialValue: _transactionType,
              decoration: const InputDecoration(labelText: 'Transaction type'),
              items: TransactionType.values
                  .map((t) => DropdownMenuItem(value: t, child: Text(t.label)))
                  .toList(),
              onChanged: (v) {
                setState(() {
                  _transactionType = v ?? _transactionType;
                  _applyTypeDefaults(accounts);
                });
              },
            ),
            const SizedBox(height: 16),
            if (_transactionType.requiresSource) ...[
              DropdownButtonFormField<String>(
                initialValue: _sourceId,
                decoration: const InputDecoration(labelText: 'Source account'),
                items: _sourceAccounts(accounts)
                    .map((a) => DropdownMenuItem(value: a.id, child: Text(a.name)))
                    .toList(),
                onChanged: (v) => setState(() => _sourceId = v),
                validator: (v) => v == null ? 'Select source account' : null,
              ),
              const SizedBox(height: 16),
            ],
            if (_transactionType.requiresDestination) ...[
              DropdownButtonFormField<String>(
                initialValue: _destinationId,
                decoration: InputDecoration(
                  labelText: _transactionType == TransactionType.investmentFunding
                      ? 'Investment funding account'
                      : 'Destination account',
                ),
                items: _destinationAccounts(accounts)
                    .map((a) => DropdownMenuItem(value: a.id, child: Text(a.name)))
                    .toList(),
                onChanged: (v) => setState(() => _destinationId = v),
                validator: (v) => v == null ? 'Select destination account' : null,
              ),
              const SizedBox(height: 16),
            ],
            if (filteredCategories.isNotEmpty)
              DropdownButtonFormField<String?>(
                initialValue: _categoryId,
                decoration: const InputDecoration(labelText: 'Category (optional)'),
                items: [
                  const DropdownMenuItem(value: null, child: Text('None')),
                  ...filteredCategories.map(
                    (c) => DropdownMenuItem(value: c.id, child: Text(c.name)),
                  ),
                ],
                onChanged: (v) => setState(() => _categoryId = v),
              ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _amountController,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(labelText: 'Amount (PKR)'),
              validator: (v) {
                final n = double.tryParse(v ?? '');
                if (n == null || n <= 0) return 'Enter a valid amount';
                return null;
              },
            ),
            const SizedBox(height: 16),
            ListTile(
              contentPadding: EdgeInsets.zero,
              title: const Text('Date'),
              subtitle: Text(AppDateUtils.formatDate(_transactionDate)),
              trailing: IconButton(
                icon: const Icon(Icons.calendar_today),
                onPressed: _isEdit ? null : _pickDate,
              ),
            ),
            const SizedBox(height: 8),
            TextFormField(
              controller: _notesController,
              decoration: const InputDecoration(labelText: 'Notes'),
              maxLines: 3,
            ),
            const SizedBox(height: 32),
            FilledButton(
              onPressed: _loading ? null : _save,
              child: _loading
                  ? const SizedBox(
                      height: 22,
                      width: 22,
                      child: CircularProgressIndicator(strokeWidth: 2),
                    )
                  : Text(_isEdit ? 'Save changes' : 'Save transaction'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:intl/intl.dart';
import '../../../shared/providers/transaction_provider.dart';
import '../../../shared/providers/account_provider.dart';
import 'package:wealthtracker/shared/models/transaction.dart';

class TransactionDetailsScreen extends ConsumerWidget {
  final String transactionId;

  const TransactionDetailsScreen({super.key, required this.transactionId});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final transaction = ref.watch(transactionProvider.notifier).getTransactionById(transactionId);
    final account = transaction != null
        ? ref.watch(accountProvider.notifier).getAccountById(transaction.accountId)
        : null;

    if (transaction == null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Transaction Not Found')),
        body: const Center(child: Text('Transaction not found')),
      );
    }

    final currencyFormat = NumberFormat.currency(symbol: 'Rs ', decimalDigits: 2);
    final dateFormat = DateFormat.yMMMMd();

    return Scaffold(
      appBar: AppBar(
        title: const Text('Transaction Details'),
        actions: [
          IconButton(
            icon: const Icon(Icons.delete),
            onPressed: () {
              showDialog(
                context: context,
                builder: (context) => AlertDialog(
                  title: const Text('Delete Transaction'),
                  content: const Text('Are you sure you want to delete this transaction?'),
                  actions: [
                    TextButton(
                      onPressed: () => context.pop(),
                      child: const Text('Cancel'),
                    ),
                    FilledButton(
                      onPressed: () {
                        ref.read(transactionProvider.notifier).deleteTransaction(transactionId);
                        context.pop();
                        context.pop();
                        ScaffoldMessenger.of(context).showSnackBar(
                          const SnackBar(content: Text('Transaction deleted')),
                        );
                      },
                      style: FilledButton.styleFrom(backgroundColor: Colors.red),
                      child: const Text('Delete'),
                    ),
                  ],
                ),
              );
            },
          ),
        ],
      ),
      body: Column(
        children: [
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(32),
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
                colors: [
                  _getTransactionColor(transaction.type),
                  _getTransactionColor(transaction.type).withAlpha(204),
                ],
              ),
            ),
            child: Column(
              children: [
                Icon(
                  _getTransactionIcon(transaction.type),
                  color: Colors.white,
                  size: 48,
                ),
                const SizedBox(height: 16),
                Text(
                  transaction.category,
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 24,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  '${transaction.type == TransactionType.income ? '+' : '-'}${currencyFormat.format(transaction.amount)}',
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 36,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ],
            ),
          ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(16),
              children: [
                _DetailRow(
                  label: 'Type',
                  value: transaction.type.name.toUpperCase(),
                ),
                _DetailRow(
                  label: 'Category',
                  value: transaction.category,
                ),
                _DetailRow(
                  label: 'Account',
                  value: account?.name ?? 'Unknown',
                ),
                _DetailRow(
                  label: 'Date',
                  value: dateFormat.format(transaction.date),
                ),
                _DetailRow(
                  label: 'Amount',
                  value: currencyFormat.format(transaction.amount),
                ),
                if (transaction.notes != null) ...[
                  const SizedBox(height: 16),
                  Card(
                    child: Padding(
                      padding: const EdgeInsets.all(16),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'Notes',
                            style: Theme.of(context).textTheme.titleSmall,
                          ),
                          const SizedBox(height: 8),
                          Text(transaction.notes!),
                        ],
                      ),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }

  Color _getTransactionColor(TransactionType type) {
    switch (type) {
      case TransactionType.income:
        return Colors.green;
      case TransactionType.expense:
        return Colors.red;
      case TransactionType.transfer:
        return Colors.blue;
    }
  }

  IconData _getTransactionIcon(TransactionType type) {
    switch (type) {
      case TransactionType.income:
        return Icons.arrow_upward;
      case TransactionType.expense:
        return Icons.arrow_upward;
      case TransactionType.transfer:
        return Icons.swap_horiz;
    }
  }
}

class _DetailRow extends StatelessWidget {
  final String label;
  final String value;

  const _DetailRow({required this.label, required this.value});

  @override
  Widget build(BuildContext context) {
    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Text(
              label,
              style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    color: Theme.of(context).colorScheme.onSurface.withAlpha(153),
                  ),
            ),
            Text(
              value,
              style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:intl/intl.dart';
import '../../../shared/providers/transaction_provider.dart';
import '../../../shared/providers/account_provider.dart';
import 'package:wealthtracker/shared/models/transaction.dart';

class TransactionDetailsScreen extends ConsumerWidget {
  final String transactionId;

  const TransactionDetailsScreen({super.key, required this.transactionId});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final transaction = ref.watch(transactionProvider.notifier).getTransactionById(transactionId);
    final account = transaction != null
        ? ref.watch(accountProvider.notifier).getAccountById(transaction.accountId)
        : null;

    if (transaction == null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Transaction Not Found')),
        body: const Center(child: Text('Transaction not found')),
      );
    }

    final currencyFormat = NumberFormat.currency(symbol: 'Rs ', decimalDigits: 2);
    final dateFormat = DateFormat.yMMMMd();

    return Scaffold(
      appBar: AppBar(
        title: const Text('Transaction Details'),
        actions: [
          IconButton(
            icon: const Icon(Icons.delete),
            onPressed: () {
              showDialog(
                context: context,
                builder: (context) => AlertDialog(
                  title: const Text('Delete Transaction'),
                  content: const Text('Are you sure you want to delete this transaction?'),
                  actions: [
                    TextButton(
                      onPressed: () => context.pop(),
                      child: const Text('Cancel'),
                    ),
                    FilledButton(
                      onPressed: () {
                        ref.read(transactionProvider.notifier).deleteTransaction(transactionId);
                        context.pop();
                        context.pop();
                        ScaffoldMessenger.of(context).showSnackBar(
                          const SnackBar(content: Text('Transaction deleted')),
                        );
                      },
                      style: FilledButton.styleFrom(backgroundColor: Colors.red),
                      child: const Text('Delete'),
                    ),
                  ],
                ),
              );
            },
          ),
        ],
      ),
      body: Column(
        children: [
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(32),
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
                colors: [
                  _getTransactionColor(transaction.type),
                  _getTransactionColor(transaction.type).withAlpha(204),
                ],
              ),
            ),
            child: Column(
              children: [
                Icon(
                  _getTransactionIcon(transaction.type),
                  color: Colors.white,
                  size: 48,
                ),
                const SizedBox(height: 16),
                Text(
                  transaction.category,
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 24,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  '${transaction.type == TransactionType.income ? '+' : '-'}${currencyFormat.format(transaction.amount)}',
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 36,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ],
            ),
          ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(16),
              children: [
                _DetailRow(
                  label: 'Type',
                  value: transaction.type.name.toUpperCase(),
                ),
                _DetailRow(
                  label: 'Category',
                  value: transaction.category,
                ),
                _DetailRow(
                  label: 'Account',
                  value: account?.name ?? 'Unknown',
                ),
                _DetailRow(
                  label: 'Date',
                  value: dateFormat.format(transaction.date),
                ),
                _DetailRow(
                  label: 'Amount',
                  value: currencyFormat.format(transaction.amount),
                ),
                if (transaction.notes != null) ...[
                  const SizedBox(height: 16),
                  Card(
                    child: Padding(
                      padding: const EdgeInsets.all(16),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'Notes',
                            style: Theme.of(context).textTheme.titleSmall,
                          ),
                          const SizedBox(height: 8),
                          Text(transaction.notes!),
                        ],
                      ),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }

  Color _getTransactionColor(TransactionType type) {
    switch (type) {
      case TransactionType.income:
        return Colors.green;
      case TransactionType.expense:
        return Colors.red;
      case TransactionType.transfer:
        return Colors.blue;
    }
  }

  IconData _getTransactionIcon(TransactionType type) {
    switch (type) {
      case TransactionType.income:
        return Icons.arrow_downward;
      case TransactionType.expense:
        return Icons.arrow_upward;
      case TransactionType.transfer:
        return Icons.swap_horiz;
    }
  }
}

class _DetailRow extends StatelessWidget {
  final String label;
  final String value;

  const _DetailRow({required this.label, required this.value});

  @override
  Widget build(BuildContext context) {
    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Text(
              label,
              style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    color: Theme.of(context).colorScheme.onSurface.withAlpha(153),
                  ),
            ),
            Text(
              value,
              style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:uuid/uuid.dart';

class NoteItem {
  final String id;
  final String text;
  final DateTime date;

  NoteItem({String? id, required this.text, required this.date}) : id = id ?? const Uuid().v4();

  Map<String, dynamic> toJson() => {
        'id': id,
        'text': text,
        'date': date.toIso8601String(),
      };

  factory NoteItem.fromJson(Map<String, dynamic> json) => NoteItem(
        id: json['id'] as String?,
        text: json['text'] as String,
        date: DateTime.parse(json['date'] as String),
      );
}

