import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'dart:convert';
import '../models/password_entry.dart';

class PasswordsNotifier extends StateNotifier<List<PasswordEntry>> {
  static const _key = 'password_entries';
  // secure storage for sensitive password data
  final FlutterSecureStorage _secure = const FlutterSecureStorage();

  PasswordsNotifier() : super([]) {
    _load();
  }

  Future<void> add(PasswordEntry entry) async {
    state = [...state, entry];
    await _save();
  }

  Future<void> update(String id, PasswordEntry entry) async {
    state = [for (final e in state) if (e.id == id) entry else e];
    await _save();
  }

  Future<void> delete(String id) async {
    state = state.where((e) => e.id != id).toList();
    await _save();
  }

  Future<void> _save() async {
    final jsonList = state.map((e) => e.toJson()).toList();
    await _secure.write(key: _key, value: jsonEncode(jsonList));
  }

  Future<void> _load() async {
    final raw = await _secure.read(key: _key);
    if (raw == null) return;
    try {
      final List<dynamic> decoded = jsonDecode(raw) as List<dynamic>;
      state = decoded.map((e) => PasswordEntry.fromJson(e as Map<String, dynamic>)).toList();
    } catch (_) {}
  }

  // Export stored password entries as JSON string (encrypted storage still used for persistence)
  Future<String> exportJson() async {
    final jsonList = state.map((e) => e.toJson()).toList();
    return jsonEncode(jsonList);
  }

  // Import entries from a JSON payload. This will replace existing entries.
  Future<void> importJson(String jsonPayload) async {
    try {
      final List<dynamic> decoded = jsonDecode(jsonPayload) as List<dynamic>;
      state = decoded.map((e) => PasswordEntry.fromJson(e as Map<String, dynamic>)).toList();
      await _save();
    } catch (e) {
      rethrow;
    }
  }

  // Export as CSV
  Future<String> exportCsv() async {
    final buffer = StringBuffer();
    buffer.writeln('id,appName,username,email,password,note,createdAt');
    for (final e in state) {
      final app = e.appName.replaceAll('"', '""');
      final user = e.username.replaceAll('"', '""');
      final email = e.email.replaceAll('"', '""');
      final pass = e.password.replaceAll('"', '""');
      final note = (e.note ?? '').replaceAll('"', '""');
      buffer.writeln('"${e.id}","$app","$user","$email","$pass","$note","${e.createdAt.toIso8601String()}"');
    }
    return buffer.toString();
  }

  // Import CSV (naive parser expecting quoted CSV rows matching export format)
  Future<void> importCsv(String csv) async {
    final lines = csv.split(RegExp(r'\r?\n')).where((l) => l.trim().isNotEmpty).toList();
    if (lines.isEmpty) return;
    if (lines.first.toLowerCase().contains('id') && lines.first.toLowerCase().contains('appname')) {
      lines.removeAt(0);
    }
    final List<PasswordEntry> parsed = [];
    final regex = RegExp(r'"(.*?)",?"(.*?)",?"(.*?)",?"(.*?)",?"(.*?)",?"(.*?)",?"(.*?)"');
    for (final line in lines) {
      final m = regex.firstMatch(line);
      if (m != null) {
        final id = m.group(1)!;
        final app = m.group(2)!.replaceAll('""', '"');
        final user = m.group(3)!.replaceAll('""', '"');
        final email = m.group(4)!.replaceAll('""', '"');
        final pass = m.group(5)!.replaceAll('""', '"');
        final note = m.group(6)!.replaceAll('""', '"');
        final created = DateTime.parse(m.group(7)!);
        parsed.add(PasswordEntry(id: id, appName: app, username: user, email: email, password: pass, note: note.isEmpty ? null : note, createdAt: created));
      }
    }
    if (parsed.isNotEmpty) {
      state = parsed;
      await _save();
    }
  }
}

final passwordsProvider = StateNotifierProvider<PasswordsNotifier, List<PasswordEntry>>((ref) => PasswordsNotifier());

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'dart:convert';
import '../models/portfolio.dart';
import '../models/transaction.dart';
import 'account_provider.dart';
import 'transaction_provider.dart';

class StockTransactionNotifier extends StateNotifier<List<StockTransaction>> {
  final Ref ref;

  StockTransactionNotifier(this.ref) : super([]) {
    _loadStockTransactions();
  }

  /// Adds a stock transaction. Returns true if successful. For BUY transactions
  /// the portfolio cash balance is checked and decreased by transaction.total.
  /// For SELL transactions the portfolio cash is increased by transaction.total.
  Future<bool> addTransaction(StockTransaction transaction) async {
    // Access portfolio cash
    final portfolioCashNotifier = ref.read(_portfolioCashProvider.notifier);
    final currentCash = ref.read(portfolioCashProvider);

    if (transaction.type == StockTransactionType.buy) {
      if (currentCash < transaction.total) {
        return false; // insufficient funds
      }
      // deduct from portfolio cash
      portfolioCashNotifier.withdraw(transaction.total);
    } else {
      // sell: add to portfolio cash
      portfolioCashNotifier.deposit(transaction.total);
    }

    state = [...state, transaction];
    await _saveStockTransactions();
    return true;
  }

  void deleteTransaction(String id) {
    state = state.where((txn) => txn.id != id).toList();
    _saveStockTransactions();
  }

  // Persistence
  static const String _stockKey = 'stock_transactions';

  Future<void> _saveStockTransactions() async {
    final prefs = await SharedPreferences.getInstance();
    final jsonList = state.map((s) => s.toJson()).toList();
    await prefs.setString(_stockKey, jsonEncode(jsonList));
  }

  Future<void> _loadStockTransactions() async {
    final prefs = await SharedPreferences.getInstance();
    final raw = prefs.getString(_stockKey);
    if (raw == null) return;
    try {
      final List<dynamic> decoded = jsonDecode(raw) as List<dynamic>;
      state = decoded
          .map((e) => StockTransaction.fromJson(e as Map<String, dynamic>))
          .toList();
    } catch (_) {}
  }

  /// Delete all transactions for a given symbol (used when deleting a holding)
  void deleteTransactionsForSymbol(String symbol) {
    state = state.where((txn) => txn.symbol != symbol).toList();
    _saveStockTransactions();
  }
}


